commands:
awk -F',' 'BEGIN {OFS=","} 
NR==1 {print; next} 
{
    email = $2
    gsub(/ /, "", email)  # Remove spaces from email
    email_lower = tolower(email)
    if (!(email_lower in seen)) {
        seen[email_lower] = 1
        print
    }
}' contacts.csv > contacts_new.csv && mv contacts_new.csv contacts.csv

awk -F',' 'BEGIN {OFS=","} 
{
  # Normalize email: lowercase and remove spaces
  email = tolower($2)
  gsub(/[[:space:]]/, "", email)
  if (!(email in seen)) {
    seen[email] = 1
    print
  }
}' contacts.csv > contacts_new.csv && mv contacts_new.csv contacts.csv

